def levenshtein(a, b):
    """Edit distance between a and b: insertions, deletions and substitutions each cost 1."""
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(
                prev[j] + 1,               # delete ca
                cur[j - 1] + 1,            # insert cb
                prev[j - 1] + (ca != cb),  # substitute, or match for free
            ))
        prev = cur
    return prev[-1]


def closest(word, candidates, max_distance=2):
    """Return the candidate nearest to word, if within max_distance; ties go to the earlier one.

    Returns None when no candidate is close enough (or candidates is empty).
    """
    if max_distance < 0:
        raise ValueError(f"max_distance must not be negative: {max_distance}")
    best, best_d = None, None
    for c in candidates:
        d = levenshtein(word, c)
        if d <= max_distance and (best_d is None or d < best_d):
            best, best_d = c, d
    return best

