import contextlib
import io
import unittest

from textkit.cli import main
from textkit.near import closest, levenshtein


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class LevenshteinTest(unittest.TestCase):
    def test_examples(self):
        self.assertEqual(levenshtein("kitten", "sitting"), 3)
        self.assertEqual(levenshtein("helo", "hello"), 1)

    def test_empty_strings(self):
        self.assertEqual(levenshtein("", ""), 0)
        self.assertEqual(levenshtein("", "abc"), 3)
        self.assertEqual(levenshtein("abc", ""), 3)

    def test_identical_and_symmetric(self):
        self.assertEqual(levenshtein("same", "same"), 0)
        self.assertEqual(levenshtein("flaw", "lawn"), levenshtein("lawn", "flaw"))


class ClosestTest(unittest.TestCase):
    def test_picks_nearest(self):
        self.assertEqual(closest("helo", ["hello", "help", "world"]), "hello")

    def test_ties_go_to_first(self):
        self.assertEqual(closest("cat", ["cot", "cab"]), "cot")
        self.assertEqual(closest("cat", ["cab", "cot"]), "cab")

    def test_none_when_too_far(self):
        self.assertIsNone(closest("zzzz", ["hello"]))

    def test_max_distance_is_inclusive(self):
        self.assertEqual(closest("abc", ["abx"], max_distance=1), "abx")
        self.assertIsNone(closest("abc", ["axy"], max_distance=1))

    def test_empty_candidates(self):
        self.assertIsNone(closest("abc", []))

    def test_negative_max_raises(self):
        with self.assertRaises(ValueError):
            closest("abc", ["abc"], max_distance=-1)


class NearCommandTest(unittest.TestCase):
    def test_prints_match(self):
        self.assertEqual(run("near", "helo", "hello", "help"), (0, "hello\n", ""))

    def test_no_match_exits_1(self):
        self.assertEqual(run("near", "zzzz", "hello"), (1, "", "no match\n"))

    def test_max_option(self):
        self.assertEqual(run("near", "helo", "world", "--max", "1"), (1, "", "no match\n"))
        self.assertEqual(run("near", "helo", "world", "--max", "3"), (0, "world\n", ""))

    def test_negative_max_exits_2(self):
        code, out, err = run("near", "helo", "hello", "--max", "-1")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error:"))

